int main() {
    // Напишите решение здесь.
    return 0;
}

additionalExercises.referenceSolution:
#include <iostream>
#include <map>
#include <memory>
#include <numbers>
#include <print>
#include <string>
#include <utility>
#include <vector>

class Shape {
public:
    virtual ~Shape() = default;
    virtual double area() const = 0;
    virtual std::unique_ptr<Shape> clone() const = 0;
};

class Circle final : public Shape {
public:
    explicit Circle(double r) : r_(r) {}
    double area() const override {
        return std::numbers::pi * r_ * r_;
    }
    std::unique_ptr<Shape> clone() const override {
        return std::make_unique<Circle>(r_);
    }

private:
    double r_;
};

class Rect final : public Shape {
public:
    Rect(double w, double h) : w_(w), h_(h) {}
    double area() const override {
        return w_ * h_;
    }
    std::unique_ptr<Shape> clone() const override {
        return std::make_unique<Rect>(w_, h_);
    }

private:
    double w_, h_;
};

class Scene {
public:
    void add(std::unique_ptr<Shape> shape) {
        shapes_.push_back(std::move(shape));
    }

    Scene clone() const {
        Scene copy;
        for (const auto &s : shapes_) {
            copy.shapes_.push_back(s->clone());
        }
        return copy;
    }

    std::size_t size() const {
        return shapes_.size();
    }

    double area() const {
        double sum = 0;
        for (const auto &s : shapes_) {
            sum += s->area();
        }
        return sum;
    }

private:
    std::vector<std::unique_ptr<Shape>> shapes_;
};

int main() {
    std::map<std::string, Scene> scenes;
    std::string command, s;
    while (std::cin >> command >> s) {
        if (command == "circle") {
            double r;
            std::cin >> r;
            scenes[s].add(std::make_unique<Circle>(r));
        } else if (command == "rect") {
            double w, h;
            std::cin >> w >> h;
            scenes[s].add(std::make_unique<Rect>(w, h));
        } else if (command == "move" || command == "clone") {
            std::string from;
            std::cin >> from;
            if (command == "move") {
                scenes[s] = std::move(scenes[from]);
            } else {
                scenes[s] = scenes[from].clone();
            }
        } else {
            const Scene &scene = scenes[s];
            std::println("{}: {} фигур, площадь {:.2f}", s, scene.size(), scene.area());
        }
    }
    return 0;
}

